settings = r'''function SettingsView() {
  const [customCategories, setCustomCategories] = useState<Record<string, string[]>>({ ...categories });
  const [newCategory, setNewCategory] = useState("");
  const [newPayment, setNewPayment] = useState("");
  const [payments, setPayments] = useState(["Conta conjunta", "Cartão principal", "Conta investimentos", "Débito automático"]);
  return <div className="mx-auto max-w-[1000px] px-4 py-5 sm:px-6 lg:py-8"><div className="mb-7"><p className="mb-2 text-[11px] font-bold uppercase tracking-[0.2em] text-[#a16d45]">Personalização</p><h1 className="font-display text-3xl font-semibold tracking-[-0.04em] text-[#173f35]">Configurações</h1><p className="mt-2 text-sm text-[#77877f]">Deixe o Fluxo com a cara da rotina financeira de vocês.</p></div><div className="grid gap-5 lg:grid-cols-2"><Card className="rounded-2xl border-[#e0e9e3] bg-white shadow-[0_8px_30px_rgba(30,62,48,0.04)]"><CardHeader className="p-5 pb-3"><CardTitle className="flex items-center gap-2 font-display text-lg text-[#173f35]"><Settings2 className="h-5 w-5 text-[#a16d45]" />Categorias e subcategorias</CardTitle></CardHeader><CardContent className="p-5 pt-2"><div className="space-y-2">{Object.entries(customCategories).map(([category, subs]) => <div key={category} className="rounded-xl bg-[#f7faf8] p-3"><div className="flex items-center justify-between"><p className="text-sm font-semibold text-[#31584b]">{category}</p><span className="text-[10px] font-bold text-[#9aa9a2]">{subs.length} itens</span></div><p className="mt-1 text-xs leading-5 text-[#8b9c94]">{subs.join(" · ")}</p></div>)}</div><div className="mt-4 flex gap-2"><Input value={newCategory} onChange={(event) => setNewCategory(event.target.value)} placeholder="Nova categoria..." className="h-10 rounded-xl border-[#dfe9e2]" /><Button onClick={() => { const value = newCategory.trim(); if (!value) return; setCustomCategories((current) => ({ ...current, [value]: ["Geral"] })); setNewCategory(""); toast.success("Categoria adicionada."); }} variant="outline" className="h-10 rounded-xl border-[#dfe9e2]"><Plus className="h-4 w-4" /></Button></div></CardContent></Card><Card className="rounded-2xl border-[#e0e9e3] bg-white shadow-[0_8px_30px_rgba(30,62,48,0.04)]"><CardHeader className="p-5 pb-3"><CardTitle className="flex items-center gap-2 font-display text-lg text-[#173f35]"><Wallet className="h-5 w-5 text-[#a16d45]" />Contas e formas de pagamento</CardTitle></CardHeader><CardContent className="space-y-3 p-5 pt-2">{payments.map((payment) => <PaymentRow key={payment} label={payment} detail={payment.includes("Conta") ? "Conta ou carteira" : "Cartão ou recorrência"} />)}<div className="flex gap-2 pt-2"><Input value={newPayment} onChange={(event) => setNewPayment(event.target.value)} placeholder="Nova conta ou cartão..." className="h-10 rounded-xl border-[#dfe9e2]" /><Button onClick={() => { const value = newPayment.trim(); if (!value) return; setPayments((current) => [...current, value]); setNewPayment(""); toast.success("Forma de pagamento adicionada."); }} variant="outline" className="h-10 rounded-xl border-[#dfe9e2]"><Plus className="h-4 w-4" /></Button></div></CardContent></Card></div></div>;
}

function PaymentRow'''

waterfall = r'''function WaterfallCard({ title, eyebrow, values }: { title: string; eyebrow: string; values: { label: string; value: number; tone: "positive" | "negative" }[] }) {
  let cumulative = 0;
  const steps = values.map((item) => { const start = cumulative; cumulative += item.value; return { ...item, start, end: cumulative }; });
  const max = Math.max(...steps.flatMap((item) => [Math.abs(item.start), Math.abs(item.end)]), 1);
  const scale = (value: number) => 132 - ((value + max) / (max * 2)) * 116;
  return <Card className="rounded-2xl border-[#e0e9e3] bg-white shadow-[0_8px_30px_rgba(30,62,48,0.04)]"><CardHeader className="p-5 pb-2"><p className="text-[10px] font-bold uppercase tracking-[0.18em] text-[#a16d45]">{eyebrow}</p><CardTitle className="mt-1 font-display text-lg text-[#173f35]">{title}</CardTitle></CardHeader><CardContent className="p-5 pt-2"><div className="h-48 w-full"><svg viewBox="0 0 620 190" className="h-full w-full" role="img" aria-label={title}><line x1="18" x2="602" y1={scale(0)} y2={scale(0)} stroke="#dfe9e2" strokeDasharray="4 5" />{steps.map((item, index) => { const x = 42 + index * (540 / steps.length); const top = scale(Math.max(item.start, item.end)); const bottom = scale(Math.min(item.start, item.end)); const height = Math.max(12, bottom - top); return <g key={item.label}><rect x={x} y={top} width={76} height={height} rx={9} fill={item.tone === "positive" ? "#b7d9c5" : "#edbcb5"} /><text x={x + 38} y={top - 8} textAnchor="middle" fontSize="11" fontWeight="700" fill={item.tone === "positive" ? "#297059" : "#a55348"}>{item.value >= 0 ? "+" : "−"}{currency(Math.abs(item.value))}</text><text x={x + 38} y="170" textAnchor="middle" fontSize="10" fill="#788a81">{item.label}</text>{index < steps.length - 1 && <line x1={x + 76} x2={x + 540 / steps.length} y1={scale(item.end)} y2={scale(item.end)} stroke="#b8c9bf" strokeDasharray="3 4" />}</g>; })}</svg></div><div className="mt-2 flex items-center justify-between rounded-xl bg-[#f5f8f5] px-3 py-2"><span className="text-xs font-semibold text-[#788a81]">Resultado acumulado</span><span className={`text-sm font-bold ${cumulative >= 0 ? "text-[#297059]" : "text-[#a55348]"}`}>{cumulative >= 0 ? "+" : "−"}{currency(Math.abs(cumulative))}</span></div></CardContent></Card>;
}

function NewTransaction'''

source = source.replace(source[source.index('function TransactionsView'):source.index('function SettingsView')], transactions)
source = source.replace(source[source.index('function SettingsView'):source.index('function PaymentRow')], settings)
source = source.replace(source[source.index('function WaterfallCard'):source.index('function NewTransaction')], waterfall)
source = source.replace('  const deleteTransaction = (id: number) => {', '  const updateTransaction = (transaction: Transaction) => setTransactions((current) => current.map((item) => item.id === transaction.id ? transaction : item));\n  const deleteTransaction = (id: number) => {')
source = source.replace('<TransactionsView transactions={transactions} onDelete={deleteTransaction} />', '<TransactionsView transactions={transactions} onDelete={deleteTransaction} onUpdate={updateTransaction} />')
path.write_text(source)
